import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Kernel 1: compute per-channel mean/var (batch statistics) and update running stats
__global__ void compute_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ mean,
    float* __restrict__ var,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int N, int C, int H, int W,
    float momentum, float eps, bool training)
{
    int c = blockIdx.x;
    long HW = (long)H * W;
    long total = (long)N * HW;

    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sumsq = sdata + blockDim.x;

    float sum = 0.0f;
    float sumsq = 0.0f;

    int tid = threadIdx.x;
    for (long idx = tid; idx < total; idx += blockDim.x) {
        long n = idx / HW;
        long hw = idx % HW;
        long offset = (n * C + c) * HW + hw;
        float val = x[offset];
        sum += val;
        sumsq += val * val;
    }

    s_sum[tid] = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sumsq[tid] += s_sumsq[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float m = s_sum[0] / (float)total;
        float v = s_sumsq[0] / (float)total - m * m;
        if (v < 0.0f) v = 0.0f;
        mean[c] = m;
        var[c] = v;

        if (training) {
            float unbiased_var = v * (float)total / (float)(total - 1);
            running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * m;
            running_var[c] = (1.0f - momentum) * running_var[c] + momentum * unbiased_var;
        }
    }
}

// Kernel 2: normalize using precomputed mean/var (fused affine transform)
__global__ void bn_normalize_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C, int H, int W,
    float eps)
{
    long HW = (long)H * W;
    long total = (long)N * C * HW;

    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)blockDim.x * gridDim.x;

    for (; idx < total; idx += stride) {
        long c = (idx / HW) % C;
        float m = mean[c];
        float v = var[c];
        float inv_std = rsqrtf(v + eps);
        float w = weight[c];
        float b = bias[c];
        y[idx] = (x[idx] - m) * inv_std * w + b;
    }
}

__global__ void bn_normalize_kernel_vec4(
    const float4* __restrict__ x,
    float4* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    long total4, int C, long HW4,
    float eps)
{
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)blockDim.x * gridDim.x;
    for (; idx < total4; idx += stride) {
        long c = (idx / HW4) % C;
        float m = mean[c];
        float v = var[c];
        float inv_std = rsqrtf(v + eps);
        float w = weight[c];
        float b = bias[c];
        float4 val = x[idx];
        float4 res;
        res.x = (val.x - m) * inv_std * w + b;
        res.y = (val.y - m) * inv_std * w + b;
        res.z = (val.z - m) * inv_std * w + b;
        res.w = (val.w - m) * inv_std * w + b;
        y[idx] = res;
    }
}
torch::Tensor batch_norm_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N, C, H, W)");
    x = x.contiguous();

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto y = torch::empty_like(x);

    auto options = x.options();
    auto mean = torch::empty({C}, options);
    auto var = torch::empty({C}, options);

    if (training) {
        int threads = 256;
        int blocks = C;
        size_t shared_mem = 2 * threads * sizeof(float);

        compute_stats_kernel<<<blocks, threads, shared_mem>>>(
            x.data_ptr<float>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            N, C, H, W,
            (float)momentum, (float)eps, true
        );
    } else {
        mean.copy_(running_mean);
        var.copy_(running_var);
    }

    long total_elems = (long)N * C * H * W;
    long HW = (long)H * W;
    int threads2 = 256;
    if ((HW % 4 == 0) && (total_elems % 4 == 0)) {
        long total4 = total_elems / 4;
        long HW4 = HW / 4;
        int blocks2 = (int)((total4 + threads2 - 1) / threads2);
        if (blocks2 > 65535) blocks2 = 65535;
        if (blocks2 < 1) blocks2 = 1;
        bn_normalize_kernel_vec4<<<blocks2, threads2>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            total4, C, HW4,
            (float)eps
        );
    } else {
        int blocks2 = (int)((total_elems + threads2 - 1) / threads2);
        if (blocks2 > 65535) blocks2 = 65535;
        bn_normalize_kernel<<<blocks2, threads2>>>(
            x.data_ptr<float>(),
            y.data_ptr<float>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            N, C, H, W,
            (float)eps
        );
    }

    return y;
}
